import { test, expect } from '@playwright/test'
import { ADMIN_AUTH, API_BASE, WEB_BASE } from '../auth.helpers'

// ── US1: Admin creates a board and adds lanes ─────────────────────────────────

test.describe('US1: Admin creates a board and adds lanes', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — admin creates a board and is assigned Owner role', async ({ page }) => {
    await page.goto(`${WEB_BASE}/`)
    await expect(page.getByRole('heading', { level: 1 })).toBeVisible()

    await page.getByRole('button', { name: /create board/i }).click()
    const nameInput = page.getByRole('textbox', { name: /board name/i })
    await nameInput.fill('Scenario 1 Board')
    await page.getByRole('button', { name: /^create$/i }).click()

    await expect(page).toHaveURL(/\/boards\/[0-9a-f-]+/, { timeout: 10_000 })
    await expect(page.getByRole('heading', { name: 'Scenario 1 Board' })).toBeVisible()
  })

  test('scenario 2 — admin adds three lanes and they appear in insertion order', async ({
    page,
    request,
  }) => {
    const boardName = `Lane Order Board ${Date.now()}`
    const createResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: boardName },
    })
    expect(createResp.ok()).toBeTruthy()
    const board = await createResp.json()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: boardName })).toBeVisible()

    for (const laneName of ['To Do', 'In Progress', 'Done']) {
      await page.getByRole('button', { name: /add lane/i }).click()
      await page.getByRole('textbox', { name: /lane name/i }).fill(laneName)
      await page.getByRole('button', { name: /^add$/i }).click()
      await expect(page.getByRole('heading', { name: laneName })).toBeVisible()
    }

    const lanes = page.getByRole('region', { name: /lane/i })
    await expect(lanes.nth(0)).toContainText('To Do')
    await expect(lanes.nth(1)).toContainText('In Progress')
    await expect(lanes.nth(2)).toContainText('Done')
  })

  test('scenario 3 — board list shows the newly created board', async ({ page, request }) => {
    const boardName = `Listed Board ${Date.now()}`
    await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })

    await page.goto(`${WEB_BASE}/`)
    await expect(page.getByText(boardName)).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 4 — duplicate board name is rejected with conflict error', async ({
    page,
    request,
  }) => {
    const boardName = `Duplicate Board ${Date.now()}`
    await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })

    await page.goto(`${WEB_BASE}/`)
    await page.getByRole('button', { name: /create board/i }).click()
    await page.getByRole('textbox', { name: /board name/i }).fill(boardName)
    await page.getByRole('button', { name: /^create$/i }).click()

    await expect(page.getByRole('alert')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 5 — duplicate lane name within a board is rejected', async ({
    page,
    request,
  }) => {
    const boardName = `Dup Lane Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: boardName },
    })
    const board = await boardResp.json()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await page.getByRole('button', { name: /add lane/i }).click()
    await page.getByRole('textbox', { name: /lane name/i }).fill('Backlog')
    await page.getByRole('button', { name: /^add$/i }).click()
    await expect(page.getByRole('heading', { name: 'Backlog' })).toBeVisible()

    await page.getByRole('button', { name: /add lane/i }).click()
    await page.getByRole('textbox', { name: /lane name/i }).fill('Backlog')
    await page.getByRole('button', { name: /^add$/i }).click()

    await expect(page.getByRole('alert')).toBeVisible({ timeout: 10_000 })
  })
})

// ── US1: Non-admin cannot create boards ──────────────────────────────────────

test.describe('US1: Non-admin user cannot create boards', () => {
  test('scenario 6 — non-admin sees no create board button', async ({ browser, request }) => {
    const uniqueEmail = `member-${Date.now()}@example.com`
    const ctx = await browser.newContext()
    const page = await ctx.newPage()

    await page.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(uniqueEmail)}&displayName=Member+User`,
    )
    await page.waitForURL(`${WEB_BASE}/**`)

    await page.goto(`${WEB_BASE}/`)

    await expect(page.getByRole('button', { name: /create board/i })).not.toBeVisible()

    await ctx.close()
  })
})

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using FluentAssertions;
using Kanban.Contracts;
using Xunit;

namespace Kanban.Tests.Integration.Api;

public sealed class LaneEndpointTests : IClassFixture<KanbanWebAppFactory>
{
    private readonly KanbanWebAppFactory _factory;

    public LaneEndpointTests(KanbanWebAppFactory factory)
    {
        _factory = factory;
    }

    // ── POST /api/v1/boards/{boardId}/lanes ───────────────────────────────────

    [Fact]
    public async Task PostLane_OwnerWithValidName_Returns201WithLaneDto()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Lane Board", adminId);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));
        var request = new { name = "To Do" };

        var response = await client.PostAsJsonAsync($"/api/v1/boards/{boardId}/lanes", request);

        response.StatusCode.Should().Be(HttpStatusCode.Created);
        var body = await response.Content.ReadFromJsonAsync<LaneDto>();
        body.Should().NotBeNull();
        body!.Name.Should().Be("To Do");
        body.Position.Should().Be(1);
        response.Headers.Location.Should().NotBeNull();
    }

    [Fact]
    public async Task PostLane_SecondLane_AppendsAtPositionTwo()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Two Lane Board", adminId);
        await _factory.InsertLaneAsync(boardId, "Lane 1", 1);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PostAsJsonAsync($"/api/v1/boards/{boardId}/lanes", new { name = "Lane 2" });

        response.StatusCode.Should().Be(HttpStatusCode.Created);
        var body = await response.Content.ReadFromJsonAsync<LaneDto>();
        body!.Position.Should().Be(2);
    }

    [Fact]
    public async Task PostLane_ViewerCaller_Returns403()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Viewer Board", adminId);
        var viewerId = await _factory.InsertStandardUserAsync("viewer@test.local");
        await _factory.InsertBoardMemberAsync(boardId, viewerId, "Viewer");
        var client = _factory.CreateAuthenticatedClient(
            TestPrincipals.RegisteredStandardUser(viewerId, "viewer@test.local"));

        var response = await client.PostAsJsonAsync($"/api/v1/boards/{boardId}/lanes", new { name = "Forbidden" });

        response.StatusCode.Should().Be(HttpStatusCode.Forbidden);
    }

    [Fact]
    public async Task PostLane_DuplicateName_Returns409()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Dup Lane Board", adminId);
        await _factory.InsertLaneAsync(boardId, "Existing", 1);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PostAsJsonAsync($"/api/v1/boards/{boardId}/lanes", new { name = "Existing" });

        response.StatusCode.Should().Be(HttpStatusCode.Conflict);
        var body = await response.Content.ReadAsStringAsync();
        body.Should().Contain("lane.name_conflict");
    }

    [Fact]
    public async Task PostLane_MissingName_Returns422()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Val Board", adminId);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PostAsJsonAsync($"/api/v1/boards/{boardId}/lanes", new { name = "" });

        response.StatusCode.Should().Be(HttpStatusCode.UnprocessableEntity);
    }

    // ── PATCH /api/v1/boards/{boardId}/lanes/{laneId} ────────────────────────

    [Fact]
    public async Task PatchLane_OwnerRenamesLane_Returns200WithUpdatedName()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Rename Board", adminId);
        var laneId = await _factory.InsertLaneAsync(boardId, "Old Name", 1);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PatchAsJsonAsync(
            $"/api/v1/boards/{boardId}/lanes/{laneId}",
            new { name = "New Name" });

        response.StatusCode.Should().Be(HttpStatusCode.OK);
        var body = await response.Content.ReadFromJsonAsync<LaneDto>();
        body!.Name.Should().Be("New Name");
    }

    [Fact]
    public async Task PatchLane_DuplicateName_Returns409()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Dup Rename Board", adminId);
        await _factory.InsertLaneAsync(boardId, "Taken", 1);
        var laneId = await _factory.InsertLaneAsync(boardId, "Original", 2);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PatchAsJsonAsync(
            $"/api/v1/boards/{boardId}/lanes/{laneId}",
            new { name = "Taken" });

        response.StatusCode.Should().Be(HttpStatusCode.Conflict);
    }

    // ── DELETE /api/v1/boards/{boardId}/lanes/{laneId} ────────────────────────

    [Fact]
    public async Task DeleteLane_OwnerCaller_Returns204()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Del Lane Board", adminId);
        var laneId = await _factory.InsertLaneAsync(boardId, "Delete Me", 1);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.DeleteAsync($"/api/v1/boards/{boardId}/lanes/{laneId}");

        response.StatusCode.Should().Be(HttpStatusCode.NoContent);
    }

    [Fact]
    public async Task DeleteLane_ViewerCaller_Returns403()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("View Del Board", adminId);
        var laneId = await _factory.InsertLaneAsync(boardId, "Protected", 1);
        var viewerId = await _factory.InsertStandardUserAsync("viewer2@test.local");
        await _factory.InsertBoardMemberAsync(boardId, viewerId, "Viewer");
        var client = _factory.CreateAuthenticatedClient(
            TestPrincipals.RegisteredStandardUser(viewerId, "viewer2@test.local"));

        var response = await client.DeleteAsync($"/api/v1/boards/{boardId}/lanes/{laneId}");

        response.StatusCode.Should().Be(HttpStatusCode.Forbidden);
    }

    // ── POST /api/v1/boards/{boardId}/lanes/{laneId}/move ────────────────────

    [Fact]
    public async Task MoveLane_OwnerWithValidVersion_Returns200()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Move Board", adminId);
        var lane1Id = await _factory.InsertLaneAsync(boardId, "Lane A", 1);
        await _factory.InsertLaneAsync(boardId, "Lane B", 2);
        await _factory.InsertLaneAsync(boardId, "Lane C", 3);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PostAsJsonAsync(
            $"/api/v1/boards/{boardId}/lanes/{lane1Id}/move",
            new { newPosition = 3, expectedVersion = 1 });

        response.StatusCode.Should().Be(HttpStatusCode.OK);
    }

    [Fact]
    public async Task MoveLane_VersionMismatch_Returns409()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Move Conflict Board", adminId);
        var laneId = await _factory.InsertLaneAsync(boardId, "Contested", 1);
        await _factory.InsertLaneAsync(boardId, "Other", 2);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PostAsJsonAsync(
            $"/api/v1/boards/{boardId}/lanes/{laneId}/move",
            new { newPosition = 2, expectedVersion = 99 });

        response.StatusCode.Should().Be(HttpStatusCode.Conflict);
        var body = await response.Content.ReadAsStringAsync();
        body.Should().Contain("lane.version_conflict");
    }

    [Fact]
    public async Task MoveLane_ViewerCaller_Returns403()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("View Move Board", adminId);
        var laneId = await _factory.InsertLaneAsync(boardId, "Read Only", 1);
        await _factory.InsertLaneAsync(boardId, "Second", 2);
        var viewerId = await _factory.InsertStandardUserAsync("viewer3@test.local");
        await _factory.InsertBoardMemberAsync(boardId, viewerId, "Viewer");
        var client = _factory.CreateAuthenticatedClient(
            TestPrincipals.RegisteredStandardUser(viewerId, "viewer3@test.local"));

        var response = await client.PostAsJsonAsync(
            $"/api/v1/boards/{boardId}/lanes/{laneId}/move",
            new { newPosition = 2, expectedVersion = 1 });

        response.StatusCode.Should().Be(HttpStatusCode.Forbidden);
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using FluentAssertions;
using Kanban.Contracts;
using Xunit;

namespace Kanban.Tests.Integration.Api;

public sealed class BoardEndpointTests : IClassFixture<KanbanWebAppFactory>
{
    private readonly KanbanWebAppFactory _factory;

    public BoardEndpointTests(KanbanWebAppFactory factory)
    {
        _factory = factory;
    }

    // ── GET /api/v1/boards ────────────────────────────────────────────────────

    [Fact]
    public async Task GetBoards_AdminWithNoBoards_ReturnsEmptyArray()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.GetAsync("/api/v1/boards");

        response.StatusCode.Should().Be(HttpStatusCode.OK);
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        body.ValueKind.Should().Be(JsonValueKind.Array);
    }

    [Fact]
    public async Task GetBoards_MemberReturnsOwnBoards_NotOtherUsersBoards()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Admin Board", adminId);
        var memberId = await _factory.InsertStandardUserAsync("member@test.local");
        await _factory.InsertBoardMemberAsync(boardId, memberId, "Member");
        var memberClient = _factory.CreateAuthenticatedClient(
            TestPrincipals.RegisteredStandardUser(memberId, "member@test.local"));
        var adminClient = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var memberResp = await memberClient.GetAsync("/api/v1/boards");
        var adminResp = await adminClient.GetAsync("/api/v1/boards");

        memberResp.StatusCode.Should().Be(HttpStatusCode.OK);
        adminResp.StatusCode.Should().Be(HttpStatusCode.OK);
    }

    [Fact]
    public async Task GetBoards_Unauthenticated_Returns401()
    {
        var client = _factory.CreateClient();

        var response = await client.GetAsync("/api/v1/boards");

        response.StatusCode.Should().Be(HttpStatusCode.Unauthorized);
    }

    // ── POST /api/v1/boards ───────────────────────────────────────────────────

    [Fact]
    public async Task PostBoards_AdminWithValidName_Returns201WithBoardDetail()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));
        var request = new { name = $"Board-{Guid.NewGuid():N}" };

        var response = await client.PostAsJsonAsync("/api/v1/boards", request);

        response.StatusCode.Should().Be(HttpStatusCode.Created);
        var body = await response.Content.ReadFromJsonAsync<BoardDetailDto>();
        body.Should().NotBeNull();
        body!.Name.Should().Be(request.name);
        body.CallerRole.Should().Be("Owner");
        response.Headers.Location.Should().NotBeNull();
    }

    [Fact]
    public async Task PostBoards_NonAdmin_Returns403()
    {
        var memberId = await _factory.InsertStandardUserAsync("nonAdmin@test.local");
        var client = _factory.CreateAuthenticatedClient(
            TestPrincipals.RegisteredStandardUser(memberId, "nonAdmin@test.local"));

        var response = await client.PostAsJsonAsync("/api/v1/boards", new { name = "Forbidden" });

        response.StatusCode.Should().Be(HttpStatusCode.Forbidden);
    }

    [Fact]
    public async Task PostBoards_DuplicateName_Returns409()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        await _factory.InsertBoardAsync("Duplicate Board", adminId);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PostAsJsonAsync("/api/v1/boards", new { name = "Duplicate Board" });

        response.StatusCode.Should().Be(HttpStatusCode.Conflict);
        var body = await response.Content.ReadAsStringAsync();
        body.Should().Contain("board.name_conflict");
    }

    [Fact]
    public async Task PostBoards_MissingName_Returns422()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.PostAsJsonAsync("/api/v1/boards", new { name = "" });

        response.StatusCode.Should().Be(HttpStatusCode.UnprocessableEntity);
    }

    // ── GET /api/v1/boards/{id} ───────────────────────────────────────────────

    [Fact]
    public async Task GetBoard_MemberCaller_Returns200WithDetail()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Detail Board", adminId);
        var client = _factory.CreateAuthenticatedClient(TestPrincipals.RegisteredAdmin(adminId));

        var response = await client.GetAsync($"/api/v1/boards/{boardId}");

        response.StatusCode.Should().Be(HttpStatusCode.OK);
        var body = await response.Content.ReadFromJsonAsync<BoardDetailDto>();
        body!.Id.Should().Be(boardId);
        body.Name.Should().Be("Detail Board");
    }

    [Fact]
    public async Task GetBoard_NonMemberCaller_Returns404()
    {
        var adminId = await _factory.GetSeededAdminIdAsync();
        var boardId = await _factory.InsertBoardAsync("Private Board", adminId);
        var nonMemberId = await _factory.InsertStandardUserAsync("nonMember@test.local");
        var client = _factory.CreateAuthenticatedClient(
            TestPrincipals.RegisteredStandardUser(nonMemberId, "nonMember@test.local"));

        var response = await client.GetAsync($"/api/v1/boards/{boardId}");

        response.StatusCode.Should().Be(HttpStatusCode.NotFound);
