        var repo = new FakeBoardRepository(boards: [board]);
        var sut = CreateSut(boardRepo: repo);

        var result = await sut.ListForCallerAsync();

        result.Should().ContainSingle(b => b.Id == boardId && b.Name == "Board A");
    }

